import { Component, computed, inject } from '@angular/core';
import { Figures } from '../../core/figures';
import { People } from '../../core/people';
import { hundredths, money } from '../../core/rates';
import { Session } from '../../core/session';

// The sheet's counters, always in view: everyone on it (retired people included), the claims in
// each status, and the sheet's due- and overdue-totals — the same figures the summary and the
// people list show. Then the same figures consolidated over the sheet and all its descendants: each
// descendant's as that sheet shows them, added to this sheet's own; while the screen shows the sheet as
// of a date, every sheet of the tree as it stood at the end of that date. And the signed-in user's own due- and overdue-totals, when a
// person on the sheet has their name or an alias equal to it; blank otherwise.
@Component({
  selector: 'app-header',
  template: `
    <header aria-label="Counters" data-testid="header">
      <dl>
        <div><dt>People</dt><dd data-testid="header-people-count">{{ people.people().length }}</dd></div>
        @for (s of figures.statusCounts(); track s.status) {
          <div><dt>{{ s.status }}</dt><dd [attr.data-testid]="'header-claims-' + s.status + '-count'">{{ s.count }}</dd></div>
        }
        <div><dt>Due total</dt><dd data-testid="header-due-total">{{ figures.dueTotal() }}</dd></div>
        <div><dt>Overdue total</dt><dd data-testid="header-overdue-total">{{ figures.overdueTotal() }}</dd></div>
        <div><dt>My due total</dt><dd data-testid="my-due-total">{{ figures.mine()?.dueTotal }}</dd></div>
        <div><dt>My overdue total</dt><dd data-testid="my-overdue-total">{{ figures.mine()?.overdueTotal }}</dd></div>
      </dl>
      <dl aria-label="Consolidated with descendant sheets">
        <div><dt>Consolidated people</dt><dd data-testid="consolidated-people-count">{{ consolidated().peopleCount }}</dd></div>
        <div><dt>Consolidated due total</dt><dd data-testid="consolidated-due-total">{{ consolidated().dueTotal }}</dd></div>
        <div><dt>Consolidated overdue total</dt><dd data-testid="consolidated-overdue-total">{{ consolidated().overdueTotal }}</dd></div>
      </dl>
    </header>
  `,
  styles: `
    header { position: sticky; top: 0; z-index: 1; background: #fff; border-bottom: 1px solid #767676; }
    dl { display: flex; flex-wrap: wrap; gap: 0.25rem 1rem; margin: 0; padding: 0.5rem 0; }
    dt, dd { display: inline; }
    dt::after { content: ': '; }
    dd { margin: 0; font-weight: bold; }
  `,
})
export class HeaderCounters {
  protected readonly people = inject(People);
  protected readonly figures = inject(Figures);
  private readonly session = inject(Session);

  protected readonly consolidated = computed(() => {
    const d = this.session.descendants();
    if (this.session.asOf()) {
      return {
        peopleCount: d.ownPeopleCount + d.peopleCount,
        dueTotal: money(hundredths(d.ownDueTotal) + hundredths(d.dueTotal)),
        overdueTotal: money(hundredths(d.ownOverdueTotal) + hundredths(d.overdueTotal)),
      };
    }
    return {
      peopleCount: this.people.people().length + d.peopleCount,
      dueTotal: money(hundredths(this.figures.dueTotal()) + hundredths(d.dueTotal)),
      overdueTotal: money(hundredths(this.figures.overdueTotal()) + hundredths(d.overdueTotal)),
    };
  });
}
import { Component, computed, inject, input, signal } from '@angular/core';
import { CrewView, Crews } from '../../core/crews';
import { Figures } from '../../core/figures';
import { People } from '../../core/people';
import { money } from '../../core/rates';

// One crew's row: its lead, its members, its due-total (the lead's and the members' due-totals as the people
// list shows them, added up, n/a skipped), and a form adding a member (its lead, or someone already in it, is
// refused).
@Component({
  selector: 'app-crew-row',
  template: `
    @let c = crew();
    <h3 data-testid="crew-name">{{ c.name }}</h3>
    <p>
      Lead: <strong data-testid="crew-lead">{{ name(c.lead) }}</strong>
      Due total: <strong data-testid="crew-due-total">{{ dueTotal() }}</strong>
    </p>
    <ul [attr.aria-label]="'Members of ' + c.name">
      @for (m of c.members; track m.personId) {
        <li data-testid="crew-member-line">{{ name(m) }}</li>
      }
    </ul>
    <form (submit)="add($event)">
      <label [for]="'crew-member-select-' + c.id">Member</label>
      <select
        [id]="'crew-member-select-' + c.id"
        data-testid="crew-member-select"
        (change)="member.set(selected($event)); error.set(null)"
      >
        <option value="" [selected]="member() === ''">Choose a person</option>
        @for (person of people.people(); track person.id) {
          <option [value]="person.id" [selected]="member() === '' + person.id">{{ person.name }}</option>
        }
      </select>
      <button type="submit" data-testid="crew-member-add" [disabled]="saving()">Add member</button>
      @if (error(); as err) {
        <p role="alert" data-testid="crew-error">{{ err }}</p>
      }
    </form>
  `,
})
export class CrewRow {
  readonly crew = input.required<CrewView>();
  protected readonly people = inject(People);
  private readonly crews = inject(Crews);
  private readonly figures = inject(Figures);
  /** The chosen person's id, or blank for none. */
  protected readonly member = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);

  /** The lead's and the members' due-totals added up, skipping those that are n/a. */
  protected readonly dueTotal = computed(() => {
    const c = this.crew();
    const ids = new Set([c.lead.personId, ...c.members.map((m) => m.personId)]);
    let sum = 0n;
    for (const p of this.people.people()) {
      if (!ids.has(p.id)) continue;
      const d = this.figures.dueCents(p);
      if (d !== null) sum += d;
    }
    return money(sum);
  });

  /** A person's name as the people list has it now; as the crew was read when they are not on it. */
  protected name(m: { personId: number; name: string }): string {
    return this.people.people().find((p) => p.id === m.personId)?.name ?? m.name;
  }

  protected selected(e: Event): string {
    return (e.target as HTMLSelectElement).value;
  }

  protected async add(e: Event): Promise<void> {
    e.preventDefault();
    if (this.saving()) return; // a second submit before the first has answered
    this.error.set(null);
    this.saving.set(true);
    try {
      const err = await this.crews.addMember(this.crew().id, this.member() ? Number(this.member()) : null);
      if (err) this.error.set(err);
      else this.member.set('');
    } finally {
      this.saving.set(false);
    }
  }
}

// The sheet's crews: a form adds one with a name and a lead (a blank name, or one already taken, is refused), and
// each crew's row shows its lead, members and due-total and adds more members.
@Component({
  selector: 'app-crews',
  imports: [CrewRow],
  template: `
    <section aria-label="Crews" data-testid="crews">
      <h2>Crews</h2>
      <form (submit)="add($event)" data-testid="crew-form">
        <label for="crew-form-name">Name</label>
        <input
          id="crew-form-name"
          data-testid="crew-form-name"
          [value]="name()"
          (input)="name.set(value($event)); error.set(null)"
        />
        <label for="crew-form-lead">Lead</label>
        <select id="crew-form-lead" data-testid="crew-form-lead" (change)="lead.set(value($event)); error.set(null)">
          <option value="" [selected]="lead() === ''">Choose a lead</option>
          @for (person of people.people(); track person.id) {
            <option [value]="person.id" [selected]="lead() === '' + person.id">{{ person.name }}</option>
          }
        </select>
        <button type="submit" data-testid="crew-form-submit" [disabled]="saving()">Add crew</button>
        @if (error(); as err) {
          <p role="alert" data-testid="crew-form-error">{{ err }}</p>
        }
      </form>
      @for (c of crews.crews(); track c.id) {
        <app-crew-row [crew]="c" [attr.data-testid]="'crew-row-' + c.name" />
      }
    </section>
  `,
})
export class CrewsPanel {
  protected readonly crews = inject(Crews);
  protected readonly people = inject(People);
  protected readonly name = signal('');
  /** The chosen lead's id, or blank for none. */
  protected readonly lead = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);

  protected value(e: Event): string {
    return (e.target as HTMLInputElement | HTMLSelectElement).value;
  }

  protected async add(e: Event): Promise<void> {
    e.preventDefault();
    if (this.saving()) return; // a second submit before the first has answered
    this.error.set(null);
    this.saving.set(true);
    try {
      const err = await this.crews.add(this.name(), this.lead() ? Number(this.lead()) : null);
      if (err) this.error.set(err);
      else {
        this.name.set('');
        this.lead.set('');
      }
    } finally {
      this.saving.set(false);
    }
  }
}
